export const BACKPACK_BRAND_GALLERY_MAP: Record<string, string[]> = {
  "mi-canvas-bag":                          BP_MI_CANVAS_BAG_IMAGES,
  "toburo-bags":                            BP_TOBURO_BAGS_IMAGES,
  "gods":                                   BP_GODS_IMAGES,
  "nasher-miles":                           BP_NASHER_MILES_IMAGES,
  "vegan-leather-products-and-accessories": BP_VEGAN_LEATHER_IMAGES,
  "travel-accessories-by-stynus-global":    BP_TRAVEL_ACCESSORIES_IMAGES,
  "toburo-felt-bags-and-bottles":           BP_TOBURO_FELT_IMAGES,
  "new-launches":                           BP_NEW_LAUNCHES_IMAGES,
};

export function getBackpackBrandImages(brandName: string): string[] | null {
  return BACKPACK_BRAND_GALLERY_MAP[slugifySegment(brandName)] ?? null;
}

export function getBackpackBrandHref(brandName: string): string {
  return `/products/backpacks/${slugifySegment(brandName)}`;
}

export function getBackpackBrandBySlug(slug: string): Product | null {
  return PRODS["Backpacks"].find((p) => slugifySegment(p.name) === slug) ?? null;
}

